import{_ as i,o as a,c as e,a5 as t}from"./chunks/framework.DrDMl0tG.js";const c=JSON.parse('{"title":"Build, Test, and Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"sections/BuildAndTest.md","filePath":"sections/BuildAndTest.md"}'),n={name:"sections/BuildAndTest.md"};function l(h,s,p,d,r,o){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="build-test-and-benchmark" tabindex="-1">Build, Test, and Benchmark <a class="header-anchor" href="#build-test-and-benchmark" aria-label="Permalink to &quot;Build, Test, and Benchmark&quot;">​</a></h1><p>This page describes the public <code>raisim2Lib</code> package workflow. The workspace downloads RaiSim and rayrai as binary packages, then builds examples and optional wrappers against those packages. It does not contain the RaiSim engine source tree. For installation and activation, see <a href="./Installation.html">Installation</a>. For repository layout and build output paths, see <a href="./ProjectLayout.html">Project Layout</a>.</p><h2 id="common-cmake-options" tabindex="-1">Common CMake options <a class="header-anchor" href="#common-cmake-options" aria-label="Permalink to &quot;Common CMake options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>RAISIM_EXAMPLE</code></td><td>Build C++ examples. Enabled by default.</td></tr><tr><td><code>RAISIM_PY</code></td><td>Build the Python wrapper (<code>raisimPy</code>). Disabled by default.</td></tr><tr><td><code>RAISIM_DOC</code></td><td>Build documentation through CMake. Disabled by default.</td></tr><tr><td><code>RAISIM_ALL</code></td><td>Shortcut that enables <code>RAISIM_EXAMPLE</code>, <code>RAISIM_PY</code>, and <code>RAISIM_DOC</code>.</td></tr><tr><td><code>RAISIM_MATLAB</code></td><td>Reserved compatibility option. The current public workspace does not add a MATLAB wrapper subdirectory or build target.</td></tr><tr><td><code>RAISIM_EXAMPLE_DESKTOP_LAUNCHER</code></td><td>Linux only. After each Release build of <code>rayrai_tcp_viewer</code>, install a desktop launcher for it and pin it to the GNOME / Ubuntu dock. Disabled by default; see <a href="./RayraiTcpViewer.html">Rayrai TCP Viewer</a>.</td></tr><tr><td><code>RAISIM_FOREST_COLLISION_BENCHMARK</code></td><td>Also build the <code>forest_collision_benchmark</code> example tool. Disabled by default.</td></tr><tr><td><code>RAISIM_DEBUG_TOOLS</code></td><td>Build manual regression and debug tools with the examples project (<code>RAISIM_EXAMPLE=ON</code>). Disabled by default; see <a href="./DebugTools.html">Regression and Debug Tools</a>.</td></tr></tbody></table><p>The RaiSim version is pinned by the checkout (<code>RAISIM_VERSION</code> in the top-level <code>CMakeLists.txt</code>). Configuring with a different <code>-DRAISIM_VERSION</code> is an error; update the checkout instead.</p><h2 id="build-examples" tabindex="-1">Build examples <a class="header-anchor" href="#build-examples" aria-label="Permalink to &quot;Build examples&quot;">​</a></h2><p>Build the package workspace with examples enabled:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/raisim2Lib</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-examples</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DCMAKE_BUILD_TYPE=Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DRAISIM_EXAMPLE=ON</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-examples</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span></span></code></pre></div><p>You can also build only the example CMake project against an installed RaiSim and rayrai package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/raisim2lib-examples</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DCMAKE_BUILD_TYPE=Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DRAISIM_PREFIX=/path/to/raisim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DRAYRAI_PREFIX=/path/to/rayrai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/raisim2lib-examples</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span></span></code></pre></div><p>Run source-built examples from the build directory. They are not installed by the <code>raisim2Lib</code> install target. A top-level build places them under <code>&lt;build-dir&gt;/examples</code>; a standalone build of <code>examples</code> places them directly in its build directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tcp_viewer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/primitive_grid</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/tmp/raisim2lib-examples/rayrai_tcp_viewer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/tmp/raisim2lib-examples/primitive_grid</span></span></code></pre></div><p>The release package does not include a prebuilt viewer. The <code>rayrai_tcp_viewer</code> target is built from the viewer sources owned by this repository and links against the packaged RaiSim and rayrai libraries.</p><h2 id="debug-and-release-package-variants" tabindex="-1">Debug and Release package variants <a class="header-anchor" href="#debug-and-release-package-variants" aria-label="Permalink to &quot;Debug and Release package variants&quot;">​</a></h2><p>The current RaiSim package can contain Debug and Release libraries in one prefix. Its exported targets map a Debug consumer to the Debug library and Release, RelWithDebInfo, and MinSizeRel consumers to a non-Debug library. <code>RSDEBUG</code> follows the selected binary automatically. If the prefix contains only one variant, every consumer configuration maps to that available variant; building a downstream project in Debug does not manufacture RaiSim debug assertions when only the Release library is installed.</p><h2 id="timing-examples" tabindex="-1">Timing examples <a class="header-anchor" href="#timing-examples" aria-label="Permalink to &quot;Timing examples&quot;">​</a></h2><p><code>raisim2Lib</code> includes standalone timing-oriented example executables. The closed-source engine benchmark runner used for RaiSim release validation is not shipped in this public binary-package workspace. Run package timing examples on one thread and repeat the same command several times when comparing package or scene changes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-examples</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anymal_standing_benchmark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> articulated_system_benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OMP_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENBLAS_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ./build-examples/examples/anymal_standing_benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fast</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OMP_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENBLAS_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ./build-examples/examples/articulated_system_benchmark</span></span></code></pre></div><p>Use <a href="./Performance.html">Performance</a> for scene-level tuning guidance and for choosing a representative package example before changing solver settings or sensor workloads in a downstream application.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>For manual object lifecycle and rendering regression checks, see <a href="./DebugTools.html">Regression and Debug Tools</a>.</p><p>The public workspace has no CTest suite; the engine&#39;s own test suite is not shipped. The examples double as smoke tests, and <code>raisimPy</code> includes a <code>unittest</code> module for its tendon bindings. Run it after building with <code>-DRAISIM_PY=ON</code>, with <code>PYTHONPATH</code> pointing to the directory that contains the built <code>raisimpy</code> module:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PYTHONPATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build/raisimPy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RAISIM_ACTIVATION_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.raisim/activation.raisim</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> raisimPy/tests/test_tendons.py</span></span></code></pre></div><h2 id="build-the-documentation" tabindex="-1">Build the documentation <a class="header-anchor" href="#build-the-documentation" aria-label="Permalink to &quot;Build the documentation&quot;">​</a></h2><p>The documentation is a <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a> site built from the Markdown pages in <code>docs</code>. Building it needs Node.js 18 or newer with npm, Python 3, and Doxygen. The <code>docs_site</code> CMake target runs the whole pipeline: Doxygen XML from the distributed headers, the API reference pages generated from it, and the site:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/raisim2Lib/docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/raisim2lib-docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DCMAKE_PREFIX_PATH=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/raisim2Lib/raisim;/path/to/raisim2Lib/rayrai&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DRAISIM_DOCS_RAISIM_INCLUDE_DIR=/path/to/raisim2Lib/raisim/include/raisim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DRAISIM_DOCS_RAYRAI_INCLUDE_DIR=/path/to/raisim2Lib/rayrai/include/rayrai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/raisim2lib-docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs_site</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/raisim2lib-docs/docs/site</span></span></code></pre></div><p>The build fails on a link to a missing page, and it then checks that every internal link and <code>#anchor</code> resolves (<code>docs/scripts/check_links.py</code>). The build writes nothing into the source tree: it copies <code>docs</code> fresh into the build directory (<code>site-src</code>) on every run, installs the Node packages there, and generates the API pages into that copy. Two build directories therefore never share any output.</p><p>The build reuses the checked-in documentation images. To regenerate those images, configure with <code>-DRAISIM_DOCS_BUILD_RAYRAI_IMAGES=ON</code>. The image generators need a working OpenGL context and overwrite the images in <code>rsc/docs/image/rayrai</code>. The option is cached, so set it back to <code>OFF</code> to stop regenerating them.</p><p>While you edit pages, the development server shows each change as you save it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/raisim2Lib/docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>Links into the API reference (<code>/api/</code>) need the generated API pages. For the development server, generate them into <code>docs/api</code> from the Doxygen XML of a documentation build:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/raisim2Lib/docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/generate_api_docs.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --xml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/raisim2lib-docs/docs/doxygen/xml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span></span></code></pre></div>`,32)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
